import pytest


def config_value(text: str, key: str) -> str:
    """Return the value for `key` in `name=value` per-line config text.

    Each line is split on the first "=". Whitespace around the name and
    the value is stripped. Blank lines, lines starting with "#", and
    lines without "=" are ignored. If the key appears more than once,
    the first occurrence wins. Returns "" when the key is absent. The
    value may itself contain "=". Does not read files.
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, val = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            return val.strip()
    return ""


def test_basic_lookup() -> None:
    assert config_value("a=1\nb=2", "b") == "2"


def test_missing_key_returns_empty() -> None:
    assert config_value("a=1\nb=2", "c") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_whitespace_stripped() -> None:
    assert config_value("  name  =  value  ", "name") == "value"


def test_value_contains_equals() -> None:
    assert config_value("url=http://x/?q=1", "url") == "http://x/?q=1"


def test_empty_value_present() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_first_occurrence_wins() -> None:
    assert config_value("a=1\na=2", "a") == "1"


def test_comments_and_blank_lines_ignored() -> None:
    text = "# a=1\n\nb=2\n"
    assert config_value(text, "a") == ""
    assert config_value(text, "b") == "2"


def test_line_without_equals_ignored() -> None:
    assert config_value("junk\na=1", "a") == "1"
    assert config_value("junk", "junk") == ""


def test_key_match_is_exact_and_case_sensitive() -> None:
    assert config_value("ab=1", "a") == ""
    assert config_value("A=1", "a") == ""


def test_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"


@pytest.mark.parametrize(
    ("text", "key", "expected"),
    [
        ("x=1", "x", "1"),
        ("x=1\ny=2", "y", "2"),
        ("x=1", "y", ""),
        ("", "", ""),
    ],
)
def test_parametrized(text: str, key: str, expected: str) -> None:
    assert config_value(text, key) == expected

